import{_ as t,a,o as d,ai as o}from"./chunks/framework.BbOtTPsL.js";const m=JSON.parse('{"title":"Customers","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/customers/main/index.md","filePath":"api/rest-api/admin/customers/main/index.md","lastUpdated":1782473079000}'),r={name:"api/rest-api/admin/customers/main/index.md"};function s(i,e,n,c,l,h){return d(),a("div",null,e[0]||(e[0]=[o('<h1 id="customers" tabindex="-1">Customers <a class="header-anchor" href="#customers" aria-label="Permalink to &quot;Customers&quot;">​</a></h1><p>The Customers menu manages the shopper accounts registered in your store — listing and searching them, viewing a full profile, and creating, editing, deleting, or bulk-managing them. It mirrors the admin <strong>Customers → Customers</strong> screen.</p><h2 id="what-a-customer-record-holds" tabindex="-1">What a customer record holds <a class="header-anchor" href="#what-a-customer-record-holds" aria-label="Permalink to &quot;What a customer record holds&quot;">​</a></h2><p>Every customer carries their identity (<code>firstName</code>, <code>lastName</code>, <code>email</code>, <code>phone</code>, <code>gender</code>, <code>dateOfBirth</code>), an enabled/suspended status, and a Customer Group they belong to. The group is returned as a nested object, and the single-record <code>GET</code> additionally returns a set of activity aggregates.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A row exists for every registered customer — whether they signed up on the storefront or were created here by an admin. Guest checkouts do <strong>not</strong> create a customer row.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>firstName</code> / <code>lastName</code> / <code>email</code> / <code>phone</code></td><td>Identity and contact details. <code>email</code> is unique across the store.</td></tr><tr><td><code>gender</code> / <code>dateOfBirth</code></td><td>Optional profile details.</td></tr><tr><td><code>status</code></td><td>Whether the account is enabled. A suspended customer cannot sign in.</td></tr><tr><td><code>group</code></td><td>The customer&#39;s group, returned as a nested object <code>{ id, code, name }</code> on both list rows and the detail response.</td></tr><tr><td><code>totalOrders</code></td><td>Count of the customer&#39;s orders. <strong>Detail-only.</strong></td></tr><tr><td><code>totalAddresses</code></td><td>Number of saved addresses. <strong>Detail-only.</strong></td></tr><tr><td><code>totalAmountSpent</code></td><td>Lifetime invoiced spend. <strong>Detail-only.</strong></td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Timestamps.</td></tr></tbody></table><p>The activity aggregates (<code>totalOrders</code>, <code>totalAddresses</code>, <code>totalAmountSpent</code>) are computed only on the single-customer <code>GET</code> — listing rows leave them null to keep the list fast.</p><h2 id="filtering-sorting-the-listing" tabindex="-1">Filtering &amp; sorting the listing <a class="header-anchor" href="#filtering-sorting-the-listing" aria-label="Permalink to &quot;Filtering &amp; sorting the listing&quot;">​</a></h2><p><code>GET /api/admin/customers</code> accepts name (first/last), <code>email</code>, <code>phone</code>, <code>customer_group_id</code>, <code>status</code>, <code>channel_id</code>, and date-of-birth / created-at ranges as query params; supplying several narrows the result (logical AND). Sort by <code>id</code> (default, descending), <code>email</code>, or <code>first_name</code>.</p><h2 id="what-create-update-delete-do" tabindex="-1">What create / update / delete do <a class="header-anchor" href="#what-create-update-delete-do" aria-label="Permalink to &quot;What create / update / delete do&quot;">​</a></h2><ul><li><strong>Create</strong> (<code>POST</code>) adds a customer. Set <code>send_password</code> (default on) to auto-generate a password and email the credentials to the customer; turn it off to supply a <code>password</code> yourself. A Customer Group is required.</li><li><strong>Update</strong> (<code>PUT</code>) edits a customer; it is partial, so send only the fields you change. Email stays unique (excluding the customer themselves); supplying a <code>password</code> re-hashes it.</li><li><strong>Delete</strong> (<code>DELETE</code>) removes a customer — blocked when they have pending or processing orders (settle or cancel those first).</li></ul><h2 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h2><ul><li><strong>Mass Delete</strong> removes several customers at once. A customer with active orders is skipped (reported under <code>skipped</code>) rather than aborting the whole batch.</li><li><strong>Mass Update Status</strong> enables or disables several customers in one call (<code>value</code> is <code>0</code> or <code>1</code>).</li></ul><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="./list.html">List Customers</a></td><td><code>GET /api/admin/customers</code></td></tr><tr><td><a href="./detail.html">Customer Detail</a></td><td><code>GET /api/admin/customers/{id}</code></td></tr><tr><td><a href="./create.html">Create Customer</a></td><td><code>POST /api/admin/customers</code></td></tr><tr><td><a href="./update.html">Update Customer</a></td><td><code>PUT /api/admin/customers/{id}</code></td></tr><tr><td><a href="./delete.html">Delete Customer</a></td><td><code>DELETE /api/admin/customers/{id}</code></td></tr><tr><td><a href="./mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/customers/mass-delete</code></td></tr><tr><td><a href="./mass-update-status.html">Mass Update Status</a></td><td><code>POST /api/admin/customers/mass-update-status</code></td></tr></tbody></table><p>Permissions: <code>customers.customers.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',19)]))}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
